    @Override protected void onActivityResult(int request,int result,Intent data){
        super.onActivityResult(request,result,data);if(MusicLibraryScreen.onActivityResult(this,request,result,data,this::libraryChanged))return;if(request==21){finishExport(result,data);return;}
        if(request==31&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getSharedPreferences("music_module",0).edit().putString("storage_tree_uri",u.toString()).apply();}catch(Exception e){Ui.error(this,e);}return;}
        if(request!=11||result!=RESULT_OK||data==null)return;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int j=0;j<data.getClipData().getItemCount();j++)uris.add(data.getClipData().getItemAt(j).getUri());}else if(data.getData()!=null)uris.add(data.getData());
        ProgressDialog importing=new ProgressDialog(this);importProgress=importing;importing.setMessage(txt("music_importing"));importing.setCancelable(false);importing.show();
        worker.submit(()->{ArrayList<MusicLibrary.Track> added=new ArrayList<>();int denied=0;for(Uri uri:uris){try{
            getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);MusicLibrary.Track old=MusicLibrary.find(this,uri.toString());if(old!=null){MusicLibrary.discover(this,Collections.singleton(MusicLibrary.readMetadata(this,uri)));added.add(MusicLibrary.find(this,uri.toString()));continue;}
            MusicLibrary.Track meta=MusicLibrary.readMetadata(this,uri);Uri stored=copyToFolder(uri,meta.title);if(stored!=null)meta=MusicLibrary.readMetadata(this,stored);added.add(meta);
        }catch(Exception e){denied++;}}
        MusicLibrary.addToQueue(this,added);final int failures=denied;main.post(()->{if(isDestroyed())return;importing.dismiss();libraryChanged();Toast.makeText(this,txt("music_imported")+added.size()+(failures>0?txt("music_grant_denied"):""),Toast.LENGTH_LONG).show();});});
    }
    private Uri copyToFolder(Uri source,String title)throws IOException{
        if(!"copy".equals(getSharedPreferences("music_module",0).getString("storage_mode","reference")))return null;String tree=getSharedPreferences("music_module",0).getString("storage_tree_uri","");if(tree.isEmpty())throw new IOException(txt("music_folder_required"));Uri treeUri=Uri.parse(tree);Uri parent=DocumentsContract.buildDocumentUriUsingTree(treeUri,DocumentsContract.getTreeDocumentId(treeUri));
        if(DocumentsContract.isDocumentUri(this,source)&&Objects.equals(source.getAuthority(),parent.getAuthority())){try{if(source.equals(parent)||DocumentsContract.isChildDocument(getContentResolver(),parent,source))return null;}catch(Exception ignored){}}
        String name=title.replaceAll("[\\\\/:*?\"<>|]","_");String mime=getContentResolver().getType(source);if(mime==null||!mime.startsWith("audio/"))mime="audio/mpeg";
        try(android.database.Cursor c=getContentResolver().query(source,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&c.getString(0)!=null)name=c.getString(0);}
        Uri dest=DocumentsContract.createDocument(getContentResolver(),parent,mime,name);if(dest==null)throw new IOException(txt("music_copy_failed"));
        try(InputStream in=getContentResolver().openInputStream(source);OutputStream out=getContentResolver().openOutputStream(dest,"wt")){if(in==null||out==null)throw new IOException();byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException();out.write(buffer,0,n);}return dest;}catch(Exception e){try{DocumentsContract.deleteDocument(getContentResolver(),dest);}catch(Exception ignored){}throw new IOException(txt("music_copy_failed"),e);}
    }
